<script setup>
import {ref,computed,watch,onMounted,onBeforeUnmount,nextTick} from 'vue';
import {Sparkles,ArrowUp,X,Settings2,Check,CheckCircle2,ChevronDown,ChevronRight,LoaderCircle,Square,RotateCcw,Eye,ArrowUpRight,ShieldCheck,Activity,Plus,Trash2,RefreshCw,KeyRound,AlertCircle,Layers,MousePointer2,Play,Copy,Download} from 'lucide-vue-next';
import {isStaticHosting} from '../../paths.js';import {providers,providerById,DEFAULT_MODEL} from '../agent/providers.js';
import {runDesignAgent,agentRequest,inspectRuntime,waitForCode} from '../agent/runtime.js';import {agentTools} from '../agent/contracts.js';import {redactForModel} from '../agent/engine.js';import {openAgentService} from '../agent/bridge.js';
import {projectFingerprint,prepareAgentTurn,finishAgentTurn} from '../agent/state.js';
import {storeGet,storePut} from '../storage.js';import AgentMessage from './AgentMessage.vue';import './agent-panel.css';
const props=defineProps({project:Object,revision:Number,selectedIds:Array,visible:Boolean,applyDesign:Function,undoDesign:Function});const emit=defineEmits(['close','draft','busy','preview','notify']);
const tab=ref('chat'),prompt=ref(''),messages=ref([]),tools=ref([]),result=ref(null),brief=ref(null),report=ref(null),busy=ref(false),applying=ref(false),stage=ref('idle'),status=ref('准备好，开始你的下一个作品。'),round=ref(0),usage=ref({input:0,output:0}),baseRevision=ref(-1),error=ref(''),notice=ref(''),settings=ref(null),loadingSettings=ref(false),settingsError=ref(''),settingsBusy=ref(false),models=ref([]),model=ref(DEFAULT_MODEL),profileId=ref(''),connection=ref(null),formOpen=ref(false),form=ref({}),content=ref(null),input=ref(null),bridging=ref(false),applied=ref(false),lastPrompt=ref(''),errorCode=ref(''),appliedRevision=ref(-1),elapsed=ref(0),lastInteraction=ref('design');const streamText=ref(''),following=ref(true);let scrollFrame;let previousDesignView=null,abort,saveTimer,checkpointTimer,checkpointPending,draftWrites=Promise.resolve(),elapsedTimer,runStarted=0,disposed=false,projectId=props.project.id,draftProjectId=projectId;
const retainedDesignRefs={result,report,brief,applied,appliedRevision,baseRevision,lastPrompt,elapsed,error,errorCode};
function restoreDesignState(saved){for(const [key,value] of Object.entries(saved))retainedDesignRefs[key].value=value;}
const conflict=computed(()=>!applied.value&&(baseRevision.value===-2||baseRevision.value>=0&&props.revision!==baseRevision.value));
const profile=computed(()=>settings.value?.profiles.find(p=>p.id===profileId.value));const canApply=computed(()=>lastInteraction.value!=='conversation'&&!!result.value?.modified&&!busy.value&&!applying.value&&!applied.value&&!conflict.value&&report.value?.errors?.length===0);
const suggestions=[{label:'新能源智慧园区',prompt:'创建新能源智慧园区大屏，深蓝银白风格，中间保留大面积园区 3D 场景，重点展示光伏发电、园区能耗和充电设施，添加光伏阵列、充电桩与可交互设备标签。使用演示数据。'},{label:'工业设备监测',prompt:'创建工业设备监测大屏，石墨钛金风格，重点突出设备效率、产能与告警，在原有车间场景添加机械臂和水泵，点击设备显示运行数据。'},{label:'精修当前作品',prompt:'保留现有业务内容与 3D 场景，精修当前大屏的标题层级、间距、配色与图表，减少多余辉光，检查遮挡与越界。'}];
function persist(){clearTimeout(saveTimer);const id=projectId;saveTimer=setTimeout(()=>storePut('settings',{id:'agent-chat:'+id,value:messages.value.slice(-16).map(m=>({role:m.role,content:m.content.slice(0,5000)}))}).catch(()=>{}),500);}
function scrollBottom(force=false){if(force)following.value=true;if(scrollFrame)return;scrollFrame=requestAnimationFrame(()=>{scrollFrame=null;nextTick(()=>{if(content.value&&following.value)content.value.scrollTop=content.value.scrollHeight;});});}
function trackScroll(){if(content.value)following.value=content.value.scrollHeight-content.value.scrollTop-content.value.clientHeight<72;}
function sizeInput(e){const el=e.target;el.style.height='auto';el.style.height=Math.min(150,Math.max(54,el.scrollHeight))+'px';}
async function loadSettings(){if(isStaticHosting)return;loadingSettings.value=true;settingsError.value='';try{settings.value=await agentRequest('settings');profileId.value=settings.value.activeProfile;model.value=(await storeGet('settings','agent-model:'+profileId.value))?.value||profile.value?.model||DEFAULT_MODEL;}catch(e){settingsError.value=e.message;if(e.status===401)settings.value={signInRequired:true,signInUrl:'/signin-with-chatgpt?return_to=%2F%3Fassistant%3D1',profiles:[]};}finally{loadingSettings.value=false;}}
async function selectProfile(){const p=profile.value;model.value=(await storeGet('settings','agent-model:'+profileId.value).catch(()=>null))?.value||p?.model||'';models.value=[];connection.value=null;if(!isStaticHosting&&profileId.value)try{await agentRequest('settings',{activeProfile:profileId.value});}catch(e){settingsError.value=e.message;}}
function editProfile(p){form.value={id:p?.managed?undefined:p?.id,name:p?.name||'',provider:p?.provider||'openrouter',baseUrl:p?.baseUrl||providerById('openrouter').baseUrl,model:p?.model||DEFAULT_MODEL,apiKey:''};formOpen.value=true;connection.value=null;}
function changeProvider(){const p=providerById(form.value.provider);form.value.baseUrl=p.baseUrl;form.value.model=p.model;form.value.apiKey='';if(!form.value.name)form.value.name=p.name;}
async function saveProfile(){settingsBusy.value=true;settingsError.value='';try{settings.value=await agentRequest('settings',{profile:form.value});profileId.value=settings.value.activeProfile;model.value=profile.value?.model||'';form.value.apiKey='';formOpen.value=false;connection.value={ok:true,message:'模型配置已加密保存'};}catch(e){settingsError.value=e.message;}finally{settingsBusy.value=false;}}
async function removeProfile(){if(!profile.value||profile.value.managed)return;settingsBusy.value=true;try{settings.value=await agentRequest('settings',{remove:profileId.value});profileId.value=settings.value.activeProfile;model.value=profile.value?.model||DEFAULT_MODEL;}catch(e){settingsError.value=e.message;}finally{settingsBusy.value=false;}}
async function fetchModels(){if(!profileId.value)return;settingsBusy.value=true;settingsError.value='';try{const r=await agentRequest('models',{profileId:profileId.value,model:model.value});models.value=r.models;if(!models.value.length)settingsError.value='厂商未返回模型列表，可直接填写模型 ID';}catch(e){settingsError.value=e.message+'；仍可手动填写模型 ID';}finally{settingsBusy.value=false;}}
async function testConnection(){settingsBusy.value=true;connection.value=null;settingsError.value='';try{const r=await agentRequest('test',{profileId:profileId.value,model:model.value});connection.value={ok:r.ok,message:r.ok?'连接成功，函数工具调用通过':'模型已连接，但没有返回工具调用；请选择支持工具的模型'};}catch(e){connection.value={ok:false,message:e.message};}finally{settingsBusy.value=false;}}
function chooseSuggestion(s){prompt.value=s.prompt;input.value?.focus();}
async function event(e){if(disposed)return;switch(e.type){case 'text-delta':streamText.value+=e.text;scrollBottom();break;case 'text-reset':streamText.value='';break;case 'stage':stage.value=e.stage;status.value=e.label;break;case 'round':round.value=e.round;break;case 'usage':usage.value=e.tokens;break;case 'notice':notice.value=e.message;break;case 'assistant':notice.value=e.content.slice(0,350);break;case 'brief':brief.value=e.brief;break;case 'evaluation':report.value=e.report;break;case 'tool-start':lastInteraction.value='design';tools.value.push({id:e.id,name:e.name,args:e.args,state:'running',open:false});break;case 'tool-result':{const t=tools.value.find(t=>t.id===e.id);if(t)Object.assign(t,{state:e.ok?'done':'error',result:e.result,duration:e.duration});break;}}}
function queueCheckpoint(base,value){checkpointPending={base,value};if(!checkpointTimer)checkpointTimer=setTimeout(flushCheckpoint,900);}
function clearCheckpoint(){clearTimeout(checkpointTimer);checkpointTimer=null;checkpointPending=null;}
async function flushCheckpoint(){clearTimeout(checkpointTimer);checkpointTimer=null;const current=checkpointPending;checkpointPending=null;if(current)await saveDraft(current.base,current.value);}
async function run(options={}){
 const text=options.retry?lastPrompt.value:prompt.value.trim();if(busy.value||applying.value||loadingSettings.value||!text)return;
 if(isStaticHosting){await bridge();return;}if(!profileId.value||!model.value){tab.value='settings';settingsError.value='请先选择一个可用的模型配置';return;}
 const savedExecution=lastInteraction.value==='conversation'?previousDesignView:{tools:tools.value,round:round.value,usage:usage.value};
 const savedDesign=Object.fromEntries(Object.entries(retainedDesignRefs).map(([key,value])=>[key,value.value]));
 let turn;try{turn=prepareAgentTurn({project:props.project,revision:props.revision,result:result.value,applied:applied.value,baseRevision:baseRevision.value,selectedIds:props.selectedIds});}catch(e){turn=prepareAgentTurn({project:props.project,revision:props.revision,selectedIds:props.selectedIds});turn.designError=e.message;}
 const resume=!!options.retry&&result.value?.modified&&!applied.value&&result.value.intent===text,previous=result.value&&!applied.value?JSON.parse(JSON.stringify({result:result.value,tools:tools.value,usage:usage.value,round:round.value})):null;
 streamText.value='';following.value=true;let completed=false;lastInteraction.value='pending';const base=turn.project,origin=turn.origin,selected=turn.selectedIds,conversation=[...messages.value];clearCheckpoint();draftProjectId=origin.id;baseRevision.value=turn.baseRevision;applied.value=false;result.value=null;report.value=null;brief.value=null;error.value='';errorCode.value='';notice.value='';tools.value=[];round.value=0;usage.value={input:0,output:0};lastPrompt.value=text;busy.value=true;emit('busy',true);prompt.value='';tab.value='chat';messages.value.push({role:'user',content:resume?'继续完成上一轮：'+text:text});persist();scrollBottom();abort=new AbortController();runStarted=Date.now();elapsed.value=0;clearInterval(elapsedTimer);elapsedTimer=setInterval(()=>elapsed.value=Math.floor((Date.now()-runStarted)/1000),1000);
 try{
  const runResult=await runDesignAgent({project:base,selectedIds:selected,mode:resume?'refine':'auto',scope:'all',prompt:text,profileId:profileId.value,model:model.value,history:conversation,resume,designError:turn.designError,canvasSource:turn.continuing?'pending-draft':'canvas',signal:abort.signal,onEvent:event,
   onDraft:async p=>{if(disposed||props.project.id!==origin.id)return;emit('draft',{project:p,baseRevision:baseRevision.value});await nextTick();},
   onCheckpoint:value=>{if(!disposed&&props.project.id===origin.id)queueCheckpoint(origin,{...value,intent:text});},
   inspect:async(p,options)=>{await nextTick();if(options?.codeNodeId)return waitForCode(options,abort.signal);return inspectRuntime(p,{...options,signal:abort.signal});}
  });
  const r=finishAgentTurn(turn,runResult);if(disposed||props.project.id!==origin.id)return;clearCheckpoint();
  if(r.kind==='conversation'){previousDesignView=savedExecution;restoreDesignState(savedDesign);lastInteraction.value='conversation';stage.value='complete';status.value='已回复，画布保持不变';messages.value.push({role:'assistant',content:r.summary});streamText.value='';return;}
  previousDesignView=null;lastInteraction.value='design';result.value={...r,intent:text};report.value=r.report;completed=true;
  if(r.noChange){emit('draft',null);baseRevision.value=-1;await draftWrites;await storePut('settings',{id:'agent-draft:'+origin.id,value:null}).catch(()=>{});}else await saveDraft(origin,result.value);
  messages.value.push({role:'assistant',content:r.summary||(r.noChange?'目标已满足，无需修改。':'设计已完成，检查通过后自动应用。')});
 }catch(e){
  if(disposed||props.project.id!==origin.id)return;clearCheckpoint();
  if(e.partial){result.value={...finishAgentTurn(turn,e.partial),intent:text};report.value=e.partial.report;await saveDraft(origin,result.value);}
  else if(previous){baseRevision.value=savedDesign.baseRevision;result.value=previous.result;report.value=previous.result.report;brief.value=previous.result.brief;tools.value=previous.tools;usage.value=previous.usage;round.value=previous.round;emit('draft',{project:previous.result.project,baseRevision:baseRevision.value});}
  else emit('draft',null);
  if(!e.partial&&!tools.value.some(t=>agentTools.find(spec=>spec.function.name===t.name)?.mutates)){previousDesignView=savedExecution;restoreDesignState(savedDesign);lastInteraction.value='conversation';}else lastInteraction.value='design';errorCode.value=e.code||'';error.value=abort.signal.aborted?'已停止，完成的部分已保留，可继续完成。':e.message;stage.value=abort.signal.aborted?'stopped':'error';status.value=error.value;messages.value.push({role:'assistant',content:error.value});
 }finally{streamText.value='';clearInterval(elapsedTimer);busy.value=false;emit('busy',false);persist();scrollBottom();}
 if(completed&&!disposed&&!abort.signal.aborted&&canApply.value)await apply(true);
}
function retryLast(){run({retry:true});}
async function undoLast(){if(!props.undoDesign||appliedRevision.value!==props.revision)return;applying.value=true;try{await props.undoDesign(appliedRevision.value);applied.value=false;result.value=null;report.value=null;brief.value=null;baseRevision.value=-1;status.value='已撤销本轮，上一版本完整保留';messages.value.push({role:'assistant',content:status.value});persist();}catch(e){error.value=e.message;}finally{applying.value=false;}}
async function apply(automatic=false){if(!canApply.value)return;const savedDraftId=draftProjectId;applying.value=true;error.value='';try{await props.applyDesign({project:result.value.project,baseRevision:baseRevision.value,mode:result.value.mode||'auto'});applied.value=true;await nextTick();appliedRevision.value=props.revision;baseRevision.value=-1;clearCheckpoint();await draftWrites;await storePut('settings',{id:'agent-draft:'+savedDraftId,value:null}).catch(()=>{});status.value=automatic===true?'已自动应用，可继续修改或撤销本轮操作':'作品已应用，所有组件仍可继续编辑';emit('draft',null);}catch(e){error.value=e.message;}finally{applying.value=false;}}
function discard(){if(busy.value)return;clearCheckpoint();draftWrites.then(()=>storePut('settings',{id:'agent-draft:'+draftProjectId,value:null})).catch(()=>{});emit('draft',null);result.value=null;report.value=null;brief.value=null;error.value='';errorCode.value='';notice.value='';previousDesignView=null;baseRevision.value=-1;stage.value='idle';status.value='草稿已收起，原稿保持不变';}
async function bridge(){bridging.value=true;try{await openAgentService(JSON.parse(JSON.stringify(props.project)),{prompt:prompt.value});emit('notify','当前项目和本机素材已带入完整服务版');}catch(e){emit('notify',e.message);}finally{bridging.value=false;}}
watch(()=>props.project.id,async id=>{if(projectId===id)return;abort?.abort();flushCheckpoint();clearTimeout(saveTimer);projectId=id;if(applying.value){persist();return;}messages.value=[];tools.value=[];previousDesignView=null;lastInteraction.value='design';brief.value=null;usage.value={input:0,output:0};round.value=0;stage.value='idle';status.value='准备好，开始你的下一个作品。';error.value='';errorCode.value='';notice.value='';applied.value=false;appliedRevision.value=-1;lastPrompt.value='';elapsed.value=0;if(!applying.value){emit('draft',null);result.value=null;report.value=null;baseRevision.value=-1;}try{const saved=await storeGet('settings','agent-chat:'+id);if(projectId===id)messages.value=saved?.value||[];}catch{}});
watch(model,value=>{if(profileId.value&&value.trim())storePut('settings',{id:'agent-model:'+profileId.value,value:value.trim()}).catch(()=>{});});
watch(()=>props.visible,value=>{if(value)nextTick(()=>input.value?.focus());});
function consumeIntent(){try{const intent=JSON.parse(sessionStorage.getItem('astra:agent-intent')||'null');if(intent){prompt.value=intent.prompt;sessionStorage.removeItem('astra:agent-intent');}}catch{}}
async function saveDraft(base,value){
 const record={id:'agent-draft:'+base.id,value:{result:value,baseProject:projectFingerprint(base),mode:value.mode||'auto',lastPrompt:lastPrompt.value,tools:tools.value.slice(-40).map(t=>({...t,args:redactForModel(t.args,0,600),result:redactForModel(t.result,0,1000)})),usage:usage.value,round:round.value}};
 draftWrites=draftWrites.catch(()=>{}).then(()=>storePut('settings',JSON.parse(JSON.stringify(record))));
 try{await draftWrites;}catch{notice.value='本机草稿存储不可用，请在关闭页面前应用或导出作品。';}
}
onMounted(async()=>{window.addEventListener('astra:agent-intent',consumeIntent);window.addEventListener('pagehide',flushCheckpoint);consumeIntent();loadSettings();try{const id=projectId,saved=await storeGet('settings','agent-chat:'+id);if(projectId!==id)return;if(!messages.value.length)messages.value=saved?.value||[];lastPrompt.value=[...messages.value].reverse().find(m=>m.role==='user')?.content||'';const draft=await storeGet('settings','agent-draft:'+id);if(projectId!==id)return;if(draft?.value?.result){draftProjectId=id;lastPrompt.value=draft.value.lastPrompt||lastPrompt.value;result.value=draft.value.result;report.value=result.value.report;brief.value=result.value.brief;tools.value=draft.value.tools||[];usage.value=draft.value.usage||result.value.tokens||{input:0,output:0};round.value=draft.value.round||result.value.rounds||0;let same=false;try{same=projectFingerprint(props.project)===projectFingerprint(JSON.parse(draft.value.baseProject));}catch{}baseRevision.value=same?props.revision:-2;if(same)emit('draft',{project:result.value.project,baseRevision:baseRevision.value});else error.value='已恢复上次草稿，但原项目已经变化，请重新生成以保留手动修改';status.value=result.value.interrupted?'已恢复执行进度，可继续完成':'已恢复上次生成的草稿';}}catch{}});
onBeforeUnmount(()=>{window.removeEventListener('astra:agent-intent',consumeIntent);window.removeEventListener('pagehide',flushCheckpoint);flushCheckpoint();clearInterval(elapsedTimer);disposed=true;cancelAnimationFrame(scrollFrame);abort?.abort();clearTimeout(saveTimer);form.value.apiKey='';});
</script>
<template><aside v-show="visible" class="aw-agent-panel" aria-label="大屏设计智能体"><header class="aa-heading"><span class="aa-orb"><Sparkles :size="18" :stroke-width="1.5"/></span><div><strong>Astra Copilot</strong><small>让想法成为作品</small></div><button class="aa-icon" aria-label="关闭智能体面板" @click="emit('close')"><X :size="17"/></button></header>
 <nav class="aa-tabs" aria-label="智能体导航"><button v-for="t in [{id:'chat',name:'对话',icon:Sparkles},{id:'settings',name:'模型设置',icon:Settings2}]" :key="t.id" :class="{active:tab===t.id}" @click="tab=t.id"><component :is="t.icon" :size="13"/>{{t.name}}</button></nav>
 <div ref="content" class="aa-content" @scroll="trackScroll"><template v-if="tab==='chat'">
  <div v-if="!messages.length" class="aa-welcome"><span class="aa-eyebrow">YOUR CREATIVE PARTNER</span><h2>从一个想法开始，<br/>让数据拥有形状。</h2><p>描述你想要的作品，或继续修改当前画布。</p><div class="aa-suggestions"><button v-for="s in suggestions" :key="s.label" @click="chooseSuggestion(s)"><span><Sparkles :size="12"/>{{s.label}}</span><ArrowUpRight :size="13"/></button></div></div>
  <div v-for="(m,i) in messages" :key="i" class="aa-message" :class="m.role"><span class="aa-message-author">{{m.role==='user'?'你':'Astra'}}</span><AgentMessage v-if="m.role==='assistant'" :content="m.content"/><p v-else>{{m.content}}</p></div>
  <div v-if="busy" class="aa-message assistant aa-stream-message" aria-label="Astra 正在回复" aria-busy="true"><span class="aa-message-author">Astra</span><AgentMessage v-if="streamText" :content="streamText" :streaming="true"/><div v-else class="aa-thinking" role="status" aria-label="正在处理"><i></i><i></i><i></i></div></div>
  <div v-if="!busy&&result" class="aa-result-actions"><template v-if="applied"><span><Check :size="12"/>已应用</span><button :disabled="!undoDesign||applying||appliedRevision!==revision" @click="undoLast"><RotateCcw :size="12"/>撤销本轮</button></template><template v-else-if="result.modified"><button v-if="canApply" :disabled="applying" @click="apply">应用到画布</button><button v-if="result.interrupted||report?.errors?.length" :disabled="applying||conflict" @click="retryLast">继续完成</button><button @click="discard">收起草稿</button></template></div>
  <p v-if="!busy&&conflict&&result?.modified&&!applied" class="aa-inline-warning" role="alert">画布已有手动修改，请重新提出修改要求，以保留最新内容。</p>
  <div v-if="!busy&&error&&!result" class="aa-result-actions"><button @click="retryLast">重试本轮</button><button v-if="errorCode.startsWith('PROVIDER_')" @click="tab='settings'">检查模型设置</button></div>
 </template>
 <template v-else><div class="aa-section-intro"><span class="aa-eyebrow">MODEL CONNECTION</span><h3>选择你的创作引擎。</h3><p>国内外模型与自定义兼容接口。默认使用 OpenRouter / Claude Haiku 5.5。</p></div>
  <div v-if="isStaticHosting" class="aa-service-note"><ShieldCheck :size="19"/><strong>模型密钥由服务端保管</strong><p>GitHub Pages 提供完整编辑能力。智能创作需要 Worker 服务；可携带当前作品与本机素材进入完整服务版。</p><button class="aa-primary" :disabled="bridging" @click="bridge">{{bridging?'正在传递项目…':'携带项目打开智能创作'}}<ArrowUpRight :size="13"/></button></div>
  <div v-else-if="settings?.signInRequired" class="aa-service-note"><KeyRound :size="19"/><strong>登录后连接你的模型</strong><p>默认模型仅向工作空间所有者开放。其他用户可以配置自己的 API Key，密钥在服务端加密保存。</p><a class="aa-primary" :href="settings.signInUrl" target="_top">登录并继续 <ArrowUpRight :size="13"/></a><button class="aa-text-button" @click="loadSettings">已登录，刷新连接</button></div>
  <template v-else-if="!loadingSettings"><label class="aa-field">模型配置<select v-model="profileId" :disabled="busy||settingsBusy" aria-label="模型配置" @change="selectProfile"><option v-if="!settings?.profiles?.length" value="">请添加模型配置</option><option v-for="p in settings?.profiles||[]" :key="p.id" :value="p.id">{{p.name}} · {{providerById(p.provider)?.name}}</option></select></label><div v-if="profile" class="aa-profile-note"><span><ShieldCheck :size="11"/>{{profile.managed?'工作空间运行时 Secret':'服务端 AES-GCM 加密'}}</span><button v-if="!profile.managed" :disabled="busy" @click="editProfile(profile)">编辑</button><button v-if="!profile.managed" class="aa-icon" :disabled="busy" aria-label="删除模型配置" @click="removeProfile"><Trash2 :size="12"/></button></div><label class="aa-field">模型 ID<div class="aa-model-input"><input v-model="model" :disabled="busy" aria-label="模型 ID" list="aa-model-list" placeholder="选择或填写模型 ID"/><button :disabled="busy||settingsBusy||!profileId" aria-label="刷新模型列表" @click="fetchModels"><RefreshCw :size="13"/></button></div><datalist id="aa-model-list"><option v-for="m in models" :key="m.id" :value="m.id">{{m.name}}</option></datalist><small>可刷新厂商模型列表，也可手动输入。</small></label><button class="aa-outline aa-wide" :disabled="busy||settingsBusy||!profileId||!model" @click="testConnection"><component :is="settingsBusy?LoaderCircle:Play" :class="{spin:settingsBusy}" :size="13"/>{{settingsBusy?'正在连接…':'测试连接与工具调用'}}</button><p v-if="connection" class="aa-connection" :class="{failed:!connection.ok}"><component :is="connection.ok?CheckCircle2:AlertCircle" :size="14"/>{{connection.message}}</p><button class="aa-new-profile" :disabled="busy" @click="editProfile()"><Plus :size="14"/>添加其他厂商或自定义接口</button>
  <form v-if="formOpen" class="aa-profile-form" @submit.prevent="saveProfile"><div><strong>{{form.id?'编辑模型配置':'新的模型连接'}}</strong><button type="button" aria-label="关闭模型表单" @click="formOpen=false;form.apiKey=''"><X :size="14"/></button></div><label class="aa-field">模型厂商<select v-model="form.provider" aria-label="模型厂商" @change="changeProvider"><option v-for="p in providers" :key="p.id" :value="p.id">{{p.name}} · {{p.region}}</option></select></label><label class="aa-field">连接名称<input v-model="form.name" aria-label="连接名称" maxlength="60" placeholder="我的创作模型"/></label><label class="aa-field">API Base URL<input v-model="form.baseUrl" aria-label="API Base URL" required type="url" placeholder="https://…/v1"/></label><label class="aa-field">模型 ID<input v-model="form.model" aria-label="新配置模型 ID" required maxlength="180"/></label><label class="aa-field">API Key<input v-model="form.apiKey" aria-label="API Key" type="password" autocomplete="off" spellcheck="false" :placeholder="form.id?'留空保留已保存的密钥':'仅发送到服务端加密保存'"/><small>密钥不会写入项目、导出包或浏览器持久存储。更换接口后需重新填写。</small></label><button class="aa-primary aa-wide" :disabled="settingsBusy"><LoaderCircle v-if="settingsBusy" class="spin" :size="13"/>加密保存连接</button></form><p class="aa-settings-foot">连接其他厂商时使用该厂商的密钥。OpenRouter 的模型也可以来自国内外不同提供方。模型需支持函数工具调用。</p></template><div v-else class="aa-empty"><LoaderCircle class="spin" :size="20"/>正在读取安全配置…</div><p v-if="settingsError" class="aa-error" role="alert"><AlertCircle :size="13"/>{{settingsError}}</p>
 </template></div>
 <footer v-if="tab==='chat'" class="aa-composer"><button v-if="!following" class="aa-jump-latest" @click="scrollBottom(true)">查看最新回复 ↓</button><div class="aa-prompt-box"><textarea ref="input" v-model="prompt" :disabled="applying" aria-label="描述你想要的大屏" rows="2" maxlength="3000" placeholder="描述想法，或修改当前作品…" @input="sizeInput" @keydown.enter.exact="!$event.isComposing&&($event.preventDefault(),!busy&&run())"></textarea><div><button class="aa-model-chip" @click="tab='settings'"><span></span>{{isStaticHosting?'连接智能服务':model===DEFAULT_MODEL?'Claude Haiku 5.5':model||'选择模型'}}<ChevronDown :size="10"/></button><button v-if="busy" class="aa-send aa-stop" aria-label="停止生成" @click="abort?.abort()"><Square :size="12" fill="currentColor"/></button><button v-else class="aa-send" :disabled="applying||loadingSettings||!prompt.trim()||bridging" aria-label="开始智能创作" @click="run"><LoaderCircle v-if="bridging" class="spin" :size="16"/><ArrowUp v-else :size="17"/></button></div></div><small>{{loadingSettings?'正在连接模型…':selectedIds.length?'已选 '+selectedIds.length+' 项 · Enter 发送':'Enter 发送 · Shift + Enter 换行'}}</small></footer>
</aside></template>
